style.css:
@-moz-document domain("roblox.com") {
/* ================================
       ROBLOX 2021 DARK HOME STYLE
       ONLY ROBLOX.COM
       ================================ */

    /* Main Roblox background */
    html,
    body {
        background: #202020 !important;
        color: #ffffff !important;
        font-family: Arial, Helvetica, sans-serif !important;
    }

    /* Main content */
    #content,
    .content,
    .container-main {
        background: #202020 !important;
    }

    /* Top Roblox navigation */
    .rbx-navbar,
    .navbar,
    .nav-container {
        background: #181818 !important;
        border-bottom: 1px solid #333 !important;
    }

    /* Navigation links */
    .rbx-navbar a,
    .navbar a {
        color: #ffffff !important;
        font-size: 13px !important;
    }

    .rbx-navbar a:hover,
    .navbar a:hover {
        background: #292929 !important;
    }

    /* Search bar */
    .navbar-search,
    .navbar-search input,
    input[placeholder*="Search"] {
        background: #111111 !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }

    /* Home page */
    .home-container,
    .games-list,
    .friend-carousel,
    .game-carousel {
        background: transparent !important;
    }

    /* Section titles */
    h1,
    h2,
    h3,
    .section-title,
    .font-header-2,
    .font-header-1 {
        color: #ffffff !important;
    }

    /* Friend circles */
    .friend,
    .friend-card,
    .friend-carousel-item {
        background: transparent !important;
        border: none !important;
    }

    /* Friend avatar */
    .avatar-card,
    .avatar-card-image,
    .avatar-image {
        border-radius: 50% !important;
    }

    /* Game cards */
    .game-card,
    .game-card-container,
    .list-item {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* Game thumbnails */
    .game-card img,
    .game-card-container img,
    .thumbnail-2d-container img {
        border-radius: 2px !important;
    }

    /* Game title */
    .game-card-name,
    .game-card-name a,
    .game-card .game-name {
        color: #ffffff !important;
        font-weight: 400 !important;
    }

    /* Game statistics */
    .game-card .text,
    .game-card .game-stat,
    .game-card .font-caption-header {
        color: #aaaaaa !important;
    }

    /* See All */
    a[href*="games"],
    .see-all {
        color: #ffffff !important;
    }

    /* Roblox cards / panels */
    .card,
    .section,
    .panel {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }

    /* Buttons */
    button {
        background: #292929 !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
        border-radius: 3px !important;
    }

    button:hover {
        background: #353535 !important;
    }

    /* Roblox blue buttons */
    .btn-primary {
        background: #00a2ff !important;
        border-color: #00a2ff !important;
        color: white !important;
    }

    /* User menu */
    .rbx-navbar-right,
    .navbar-right {
        background: transparent !important;
    }

    /* Notifications */
    .notification,
    .notifications {
        background: #202020 !important;
        border-color: #444 !important;
    }

    /* Dropdown menus */
    .dropdown-menu,
    .popover,
    .menu {
        background: #242424 !important;
        border: 1px solid #444 !important;
    }

    .dropdown-menu a:hover,
    .menu a:hover {
        background: #333 !important;
    }

    /* Footer */
    footer,
    .footer {
        background: #181818 !important;
        border-top: 1px solid #333 !important;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px !important;
        height: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: #181818 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #444 !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #555 !important;
    }

    /* Remove modern rounded/glass effects */
    [style*="backdrop-filter"] {
        backdrop-filter: none !important;
    }

    /* Keep Roblox UI compact like older versions */
    .game-card {
        margin-right: 6px !important;
    }

    /* Dark separators */
    hr {
        border-color: #333 !important;
    }
}
